    <script>
        $(document).ready(function () {
             $('#dataTable .edit').attr('target', '_blank');
            $('[data-toggle="tooltip"]').tooltip();

            $('#daterange').datepicker({
                format: "mm/yyyy",
                startView: 1,
                minViewMode: 1,
                maxViewMode: 2,
                language: "fr"
            });

            $('.verify').click(function (e) {
                e.preventDefault();
                $('#search_modal').modal('show');
                $('#search-spinner').fadeIn(300);
                $('#search-table').fadeOut(300);
                $('#search-table').html('');

                var form = $('#form-filtre').serialize();
                var agence = $('select[name="agence"]').val();
                var url = '{{ url('') }}';

                $.ajax({
                    url: "{{ url('paiements/status') }}",
                    method: "POST",
                    dataType: 'json',
                    cache: false,
                    data: form,
                    success: function(result) {
                        if(result.diff == "danger") {
                            $('#search-table').append('<p class="alert alert-danger">'+
                                'Nous n\'avons trouvé aucun paiement pour ce mois, merci de contacter l\'agence Ou il est trop tôt pour effectuer les paiements'+
                                '</p>'
                            );
                        }
                        else if(result.diff == "warning") {
                            $('#search-table').append(
                                '<p class="alert alert-warning">'+
                                'Il y a des paiements impayés, merci de contacter l\'agence pour compléter les paiements'+
                                '</p>'
                            );
                        }
                        else {
                            $('#search-table').append(
                                '<p class="alert alert-success">'+
                                    'Super!! tous les paiements sont payés'+
                                '</p>'
                            );
                        }

                        $('#search-table').append(
                            '<div class="row" style="margin-right: 0;margin-left: 0;">'+
                                '<div class="col-sm-4">'+
                                    '<ul class="list-group">'+
                                      '<li class="list-group-item">Total des paiements</li>'+
                                      '<li class="list-group-item"><label class="label label-success">'+result.sum_paiment+'</label></li>'+
                                      '<li class="list-group-item">'+result.currency+'</li>'+
                                    '</ul>'+
                                '</div>'+
                                '<div class="col-sm-4">'+
                                    '<ul class="list-group">'+
                                      '<li class="list-group-item">Total des reservations</li>'+
                                      '<li class="list-group-item"><label class="label label-primary">'+result.sum_resa+'</label></li>'+
                                      '<li class="list-group-item">'+result.currency+'</li>'+
                                    '</ul>'+
                                '</div>'+
                                '<div class="col-sm-4">'+
                                    '<ul class="list-group">'+
                                      '<li class="list-group-item">Paiements restants</li>'+
                                      '<li class="list-group-item"><label class="label label-danger">'+(result.sum_resa-result.sum_paiment).toFixed(2)+'</label></li>'+
                                      '<li class="list-group-item">'+result.currency+'</li>'+
                                    '</ul>'+
                                '</div>'+
                            '</div>'
                        );

                        $('#search-table').append('<a href="'+url+'/reservations?date='+result.date+'&key=agence_id&filter=equals&s='+agence+'" target="_blank" class="btn btn-success pull-right">Afficher les réservations <i class="icon voyager-double-right"></i></a>'
                        );

                        $('#search-spinner').fadeOut(300);
                        $('#search-table').fadeIn(300);
                    }
                });
            });

